import { configureStore, combineReducers } from '@reduxjs/toolkit';

export function createInjectableStore() {
  const reducerMap = {};

  const rootReducer = combineReducers(reducerMap);
  const store = configureStore({ reducer: rootReducer });

  // Replace the root reducer so newly-injected keys are picked up
  store.injectReducer = (key, reducer) => {
    if (reducerMap[key]) return; // already injected
    reducerMap[key] = reducer;
    store.replaceReducer(combineReducers(reducerMap));
  };

  return store;
}

import { useEffect } from 'react';
import { useStore } from 'react-redux';

export function useInjectReducer(key, reducer) {
  const store = useStore();
  useEffect(() => {
    store.injectReducer(key, reducer);
  }, [store, key, reducer]);
}

import React, { useEffect, lazy } from 'react';
import { useInjectReducer } from './useInjectReducer';

